#include <bits/stdc++.h>
using namespace std;using ll=long long;const ll INF=(1LL<<62);
struct V{ll p,m,c;};
V join(V a,V b){return {min(a.p,b.p),min(a.m,b.m),min({a.c,b.c,a.p+b.m})};}
struct Seg{int n;vector<V> t;vector<ll> lp,lm;Seg(int n):n(n),t(4*n+4,{INF,INF,INF}),lp(4*n+4),lm(4*n+4){}void build(int x,int l,int r,const vector<ll>&c,const vector<ll>&b){if(l==r){t[x]={b[l]+c[l],b[l]-c[l],INF};return;}int q=(l+r)/2;build(x*2,l,q,c,b);build(x*2+1,q+1,r,c,b);t[x]=join(t[x*2],t[x*2+1]);}void app(int x,ll p,ll m){t[x].p+=p;t[x].m+=m;lp[x]+=p;lm[x]+=m;}void push(int x){if(lp[x]||lm[x]){app(x*2,lp[x],lm[x]);app(x*2+1,lp[x],lm[x]);lp[x]=lm[x]=0;}}void add(int x,int l,int r,int ql,int qr,ll d){if(ql>r||qr<l)return;if(ql<=l&&r<=qr){app(x,d,-d);return;}push(x);int q=(l+r)/2;add(x*2,l,q,ql,qr,d);add(x*2+1,q+1,r,ql,qr,d);t[x]=join(t[x*2],t[x*2+1]);}void point(int x,int l,int r,int at,ll d){if(l==r){t[x].p+=d;t[x].m+=d;return;}push(x);int q=(l+r)/2;if(at<=q)point(x*2,l,q,at,d);else point(x*2+1,q+1,r,at,d);t[x]=join(t[x*2],t[x*2+1]);}V get(int x,int l,int r,int ql,int qr){if(ql>r||qr<l)return {INF,INF,INF};if(ql<=l&&r<=qr)return t[x];push(x);int q=(l+r)/2;return join(get(x*2,l,q,ql,qr),get(x*2+1,q+1,r,ql,qr));}};
int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int T;cin>>T;while(T--){int n,q;cin>>n>>q;vector<ll>a(n+1),b(n+1),c(2*n+1);for(int i=1;i<=n;i++)cin>>a[i];for(int i=1;i<=n;i++)cin>>b[i];ll total=0;for(int i=1;i<=n;i++){c[i]=total;total+=a[i];}for(int i=1;i<=n;i++)c[n+i]=total+c[i];vector<ll>bb(2*n+1);for(int i=1;i<=2*n;i++)bb[i]=b[(i-1)%n+1];Seg st(2*n);st.build(1,1,2*n,c,bb);auto add=[&](int l,int r,ll d){if(l<=r)st.add(1,1,2*n,l,r,d);};auto point=[&](int x,ll d){st.point(1,1,2*n,x,d);};auto getC=[&](int x){return st.get(1,1,2*n,x,x).p-b[(x-1)%n+1];};
  while(q--){int typ;cin>>typ;if(typ==1){int s,t;cin>>s>>t;ll cs=getC(s),cns=getC(n+s);if(t==n+1){V f=st.get(1,1,2*n,s,n+s-1),r=st.get(1,1,2*n,s+1,n+s);cout<<min(f.p-cs,r.m+cns)<<'\n';}else{ll ct=getC(t);V f=st.get(1,1,2*n,s,t),r=st.get(1,1,2*n,t,n+s);ll ans=min(ct-cs,total-ct+cs);ans=min(ans,f.c-cs+ct);ans=min(ans,r.c-ct+cns);V fp=st.get(1,1,2*n,s,t-1),rp=st.get(1,1,2*n,t,n+s-1);ans=min(ans,fp.p-cs+rp.p-ct);if(t+1<=n+s-1){V rm=st.get(1,1,2*n,t+1,n+s-1),fm=st.get(1,1,2*n,s+1,t);ans=min(ans,rm.m+cns+fm.m+ct);}cout<<ans<<'\n';}}
 else if(typ==2){int x;ll w;cin>>x>>w;ll d=w-a[x];a[x]=w;total+=d;add(x+1,n,d);add(n+1,n+x,d);add(n+x+1,2*n,2*d);}
 else{int x;ll w;cin>>x>>w;ll d=w-b[x];b[x]=w;point(x,d);point(n+x,d);}}
 }}
